import {bindProfilePhoto,profilePhotoPicker} from './profile-photo-picker.mjs';
let api,success,stage='choose',login=false;
export function initBrosJoin(callbacks){api=callbacks;const root=document.createElement('section');root.id='bros-join';document.body.append(root);root.addEventListener('click',ev=>{const b=ev.target.closest('[data-bros]');if(!b)return;switch(b.dataset.bros){case 'back':if(stage==='choose'){document.body.classList.remove('bros-join-mode');api.back();}else{stage='choose';render();}break;case 'nickname':stage='nickname';login=false;render();break;case 'full':document.body.classList.remove('bros-join-mode');api.full(success);break;case 'login':login=!login;render();break;case 'password':{const field=document.querySelector('#bros-password');field.type=field.type==='password'?'text':'password';b.textContent=field.type==='password'?'Hiện':'Ẩn';break;}}});}
export async function showBrosJoin(callback){success=callback;try{const response=await fetch('/api/auth/me',{credentials:'same-origin'});const {user}=await response.json();if(response.ok&&user?.role==='Bros'){success(user);return;}}catch{}stage='choose';login=false;document.body.classList.remove('onboarding','broke-mode','messages-mode','registration-mode','debts-mode');document.body.classList.add('bros-join-mode');render();window.scrollTo(0,0);}
function render(){document.querySelector('#bros-join').innerHTML=`<div class="registration-top"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"><button data-bros="back">← ${stage==='choose'?'Quay lại':'Đổi cách tham gia'}</button></div><div class="bros-join-content"><img class="bros-join-mark" src="assets/debtfreelately-mark-clean.png" alt=""><p class="registration-eyebrow">WELCOME, BROS</p><h1>${stage==='choose'?'Bạn muốn bắt đầu thế nào?':login?'Chào mừng bạn trở lại.':'Một biệt danh. Một khởi đầu.'}</h1><p class="bros-join-description">${stage==='choose'?'Chọn cách tham gia phù hợp với bạn và bắt đầu đồng hành cùng Broke.':login?'Đăng nhập bằng biệt danh và mật khẩu của bạn.':'Tạo tài khoản nhanh để vào tìm Broke ngay.'}</p>${stage==='choose'?`<div class="bros-join-options"><button data-bros="nickname"><span class="bros-option-icon">☆</span><small>BẮT ĐẦU NHANH</small><h2>Biệt danh & mật khẩu</h2><p>Chọn một tên riêng, không trùng với người khác.<br>Không cần email để bắt đầu.</p><strong>Vào tìm Broke ngay →</strong></button><button data-bros="full"><span class="bros-option-icon">♙</span><small>ĐĂNG KÝ ĐẦY ĐỦ</small><h2>Thông tin cá nhân</h2><p>Họ tên thật, giới tính, tuổi, điện thoại và email.<br>Xác minh email bằng mã xác nhận.</p><strong>Đăng ký tài khoản đầy đủ →</strong></button></div><p class="bros-join-footnote">No one gets debt-free alone.</p>`:`<form id="bros-nickname-form" class="registration-card bros-nickname-form"><label for="bros-nickname">Biệt danh ${login?'':'duy nhất'}</label><input id="bros-nickname" name="nickname" autocomplete="username" minlength="3" maxlength="30" required placeholder="Ví dụ: KindBros_2026"><p class="registration-caption">3–30 ký tự: chữ, số, dấu chấm, gạch ngang hoặc gạch dưới. Không phân biệt chữ hoa/thường.</p><label for="bros-password">Mật khẩu</label><div class="bros-password-row"><input id="bros-password" name="password" type="password" autocomplete="${login?'current-password':'new-password'}" minlength="8" maxlength="128" required placeholder="Ít nhất 8 ký tự"><button type="button" data-bros="password">Hiện</button></div>${login?'':profilePhotoPicker()}<p class="form-error" role="alert" id="bros-nickname-error"></p><button class="registration-submit">${login?'Đăng nhập & tìm Broke':'Tạo tài khoản & tìm Broke'} <span>→</span></button><p class="registration-caption bros-password-note">Tài khoản biệt danh chưa có email khôi phục. Hãy lưu mật khẩu ở nơi an toàn.</p><div class="registration-switch">${login?'Chưa có tài khoản?':'Đã có biệt danh?'} <button type="button" data-bros="login">${login?'Đăng ký nhanh':'Đăng nhập'}</button></div></form>`}</div>`;
const form=document.querySelector('#bros-nickname-form');const readPhoto=form&&!login?bindProfilePhoto(form):null;if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('.registration-submit'),error=document.querySelector('#bros-nickname-error');b.disabled=true;error.textContent='';try{const body=Object.fromEntries(new FormData(form));if(readPhoto)body.photo=await readPhoto();const response=await fetch('/api/auth/'+(login?'nickname-login':'nickname-signup'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'Không thể tạo tài khoản.');document.body.classList.remove('bros-join-mode');form.reset();success(data.user);api.toast(login?'Đã đăng nhập. Chào mừng Bros!':'Tài khoản đã được tạo. Cùng tìm một câu chuyện nhé!');}catch(err){error.textContent=err.message;b.disabled=false;}};
}

